effect.shader:
void main() {
    vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
    vec4 white = vec4(1.,1.,1.,1.);
    vec3 color = vec3(progressa, progressb, progressc);
    vec4 result;
    if( blendMode==1 ) {
        result = vec4((texColor.rgb/texColor.a)*color.rgb,1.0) * texColor.a;
    } else if( blendMode==2 ) {
        result = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-color.rgb)),1.0) * texColor.a;
    } else {
        result = vec4(color.rgb,1.0)*texColor.a;
    }
    // gl_FragColor = texture2D(noisexx.texture, (gl_FragCoord.xy*progressa));
    gl_FragColor = mix(white,result,alpha);
}
